export type CalendarAction2 =
  | { type: 'SELECT_DATE'; date: string }
  | { type: 'SELECT_WEEK'; startDate: string }
  | { type: 'SELECT_MONTH'; year: number; month: number }
  | { type: 'SET_FILTERS'; payload: TaskTypeValue[] }
  | { type: 'VIEW_ALL' }
  | { type: 'NAV_MONTH'; payload: -1 | 1 };

export function calendarReducer(
  state: CalendarPageState,
  action: CalendarAction2,
): CalendarPageState {
  switch (action.type) {
    case 'SELECT_DATE':
      return {
        ...state,
        selectedRange: { type: 'day', startDate: action.date, endDate: action.date },
        viewAllMode: false,
      };
    case 'SELECT_WEEK': {
      const start = dayjs(action.startDate);
      return {
        ...state,
        selectedRange: {
          type: 'week',
          startDate: action.startDate,
          endDate: start.add(6, 'day').format('YYYY-MM-DD'),
        },
        viewAllMode: false,
      };
    }
    case 'SELECT_MONTH': {
      const m = dayjs(`${action.year}-${String(action.month).padStart(2, '0')}-01`);
      return {
        ...state,
        selectedRange: {
          type: 'month',
          startDate: m.format('YYYY-MM-DD'),
          endDate: m.endOf('month').format('YYYY-MM-DD'),
        },
        viewAllMode: false,
      };
    }
    case 'SET_FILTERS':
      return { ...state, taskTypeFilters: action.payload };
    case 'VIEW_ALL':
      return { ...state, viewAllMode: true, selectedRange: null };
    case 'NAV_MONTH': {
      const m = dayjs(state.baseMonth + '-01');
      return { ...state, baseMonth: m.add(action.payload, 'month').format('YYYY-MM') };
    }
    default:
      return state;
  }
}

function buildQuery(state: CalendarPageState): string {
  const params = new URLSearchParams();
  params.set('page', '1');
  params.set('pageSize', '20');

  if (state.taskTypeFilters.length > 0 && state.taskTypeFilters.length < 3) {
    params.set('taskType', state.taskTypeFilters.join(','));
  }

  if (!state.viewAllMode && state.selectedRange) {
    params.set('startDate', state.selectedRange.startDate);
    params.set('endDate', state.selectedRange.endDate);
  }

  return `/task-assignments?${params.toString()}`;
}

export function ParentTasksPage() {
  // ── 日历状态管理 ──
  const now = dayjs();
  const todayStr = now.format('YYYY-MM-DD');
  const [calendarState, dispatch] = useReducer(calendarReducer, {
    baseMonth: now.format('YYYY-MM'),
    // fix-build 第三次迭代: type=day + today 单点（取消整周高亮）。
    // 初始状态：仅 today cell 高亮（teal 实心）+ 当周蓝色边框。
    selectedRange: {
      type: 'day',
      startDate: todayStr,
      endDate: todayStr,
    },
    taskTypeFilters: ['LIMITED', 'REPEAT', 'STANDING'],
    viewAllMode: false,
  });

  // 动态构建查询参数（debounce 300ms），初始值与 buildQuery 保持一致
  const debounceTimer = useRef<ReturnType<typeof setTimeout>>();
  const [queryPath, setQueryPath] = useState(() => buildQuery(calendarState));

  useEffect(() => {
    if (debounceTimer.current) clearTimeout(debounceTimer.current);
    debounceTimer.current = setTimeout(() => {
      setQueryPath(buildQuery(calendarState));
    }, 300);
    return () => {
      if (debounceTimer.current) clearTimeout(debounceTimer.current);
    };
  }, [calendarState]);

  const { data, loading, error, refetch } = useApi<PageResult<TaskAssignment>>(queryPath);
  const { data: templates } = useApi<PageResult<TaskTemplate>>('/task-templates?enabled=true');
  const { data: children } = useApi<PageResult<ChildProfile>>('/family/children');
  const childNameMap = useMemo(() => {
    const map = new Map<number, string>();
    for (const c of children?.content ?? []) {
      map.set(c.id, c.nickname);
    }
    return map;
  }, [children]);
  const [showAssign, setShowAssign] = useState(false);
  const templateId = useFormField();
  const difficultyId = useFormField();
  const startDate = useFormField();
  const endDate = useFormField();
  const { setValue: setDifficultyId } = difficultyId;
  const { setValue: setStartDate } = startDate;
  const { setValue: setEndDate } = endDate;
  const [childIds, setChildIds] = useState<number[]>([]);
  const online = useOnline();
  const [assigning, setAssigning] = useState(false);
  const idempotencyKey = useIdempotencyKey();

  // 单任务分配状态
  const [showSingleAssign, setShowSingleAssign] = useState(false);
  const singleTemplateId = useFormField();
  const singleDifficultyId = useFormField();
  const singleChildId = useFormField();
  const [singleDeadline, setSingleDeadline] = useState('');
  const [singleAssigning, setSingleAssigning] = useState(false);

  const selectedSingleTemplate = useMemo(() => {
    return (templates?.content ?? []).find((t) => String(t.id) === singleTemplateId.value);
  }, [templates, singleTemplateId.value]);

  const singleEnabledDifficulties = useMemo(() => {
    return (selectedSingleTemplate?.difficulties ?? []).filter((d) => d.enabled);
  }, [selectedSingleTemplate]);

  const resetSingleAssignForm = () => {
    singleTemplateId.reset();
    singleDifficultyId.reset();
    singleChildId.reset();
    setSingleDeadline('');
  };

  const handleSingleAssign = async () => {
    const tId = Number(singleTemplateId.value);
    const dId = Number(singleDifficultyId.value);
    const cId = Number(singleChildId.value);
    if (!tId || !dId || !cId) {
      message.error('请选择模板、难度和孩子');
      return;
    }

    const isRepeat = selectedSingleTemplate?.taskType === 'REPEAT';

    if (isRepeat) {
      // 重复任务：不需要任何日期，直接创建分配
      setSingleAssigning(true);
      const res = await getClient().post('/task-assignments', {
        templateId: tId,
        childId: cId,
        difficultyId: dId,
      });
      setSingleAssigning(false);
      if (res.error) {
        message.error(res.error.message ?? '分配失败');
        return;
      }
      setShowSingleAssign(false);
      resetSingleAssignForm();
      message.success('重复任务已分配');
      await refetch();
    } else {
      // 非重复任务：需要截止日期
      if (!singleDeadline) {
        message.error('请选择截止日期');
        return;
      }
      setSingleAssigning(true);
      const res = await getClient().post('/task-assignments', {
        templateId: tId,
        childId: cId,
        difficultyId: dId,
        deadline: `${singleDeadline}T23:59:59`,
      });
      setSingleAssigning(false);
      if (res.error) {
        message.error(res.error.message ?? '分配失败');
        return;
      }
      setShowSingleAssign(false);
      resetSingleAssignForm();
      message.success('任务已分配');
      await refetch();
    }
  };

  const selectedTemplate = useMemo(() => {
    return (templates?.content ?? []).find((t) => String(t.id) === templateId.value);
  }, [templates, templateId.value]);

  const enabledDifficulties = useMemo(() => {
    return (selectedTemplate?.difficulties ?? []).filter((d) => d.enabled);
  }, [selectedTemplate]);

  useEffect(() => {
    if (selectedTemplate && enabledDifficulties.length > 0) {
      const first = enabledDifficulties[0];
      if (String(first.id) !== difficultyId.value) {
        setDifficultyId(String(first.id));
      }
    } else if (!selectedTemplate) {
      setDifficultyId('');
    }
  }, [selectedTemplate, enabledDifficulties, difficultyId.value, setDifficultyId]);

  // 根据所选模板的任务类型自动填入日期
  useEffect(() => {
    if (!selectedTemplate) {
      setStartDate('');
      setEndDate('');
      return;
    }
    const today = new Date().toISOString().split('T')[0];
    if (selectedTemplate.taskType === 'LIMITED') {
      try {
        const config = selectedTemplate.typeConfig ? JSON.parse(selectedTemplate.typeConfig) : {};
        setStartDate((config.start_date as string) || today);
        setEndDate((config.end_date as string) || today);
      } catch {
        setStartDate(today);
        setEndDate(today);
      }
    } else {
      // REPEAT / STANDING：默认只填开始日期，结束日期与开始日期保持一致
      setStartDate(today);
      setEndDate(today);
    }
  }, [selectedTemplate, setStartDate, setEndDate]);

  const resetAssignForm = () => {
    templateId.reset();
    difficultyId.reset();
    startDate.reset();
    endDate.reset();
    setChildIds([]);
  };

  const handleAssign = async () => {
    const tId = Number(templateId.value);
    const dId = Number(difficultyId.value);
    if (!tId || !dId) {
      Modal.error({ title: '错误', content: '请选择模板和难度' });
      return;
    }
    if (childIds.length === 0) {
      Modal.error({ title: '错误', content: '请至少选择一个孩子' });
      return;
    }
    const isRepeat = selectedTemplate?.taskType === 'REPEAT';
    const payloadStartDate = startDate.value;
    const payloadEndDate = isRepeat ? payloadStartDate : endDate.value;
    if (!payloadStartDate || !payloadEndDate) {
      Modal.error({ title: '错误', content: '请填写开始日期和结束日期' });
      return;
    }
    if (payloadStartDate > payloadEndDate) {
      Modal.error({ title: '错误', content: '开始日期不得晚于结束日期' });
      return;
    }

    setAssigning(true);
    const res = await getClient().post('/task-assignments/batch', {
      templateId: tId,
      difficultyId: dId,
      startDate: payloadStartDate,
      endDate: payloadEndDate,
      childIds,
      idempotencyKey,
    });
    setAssigning(false);
    if (res.error) {
      Modal.error({ title: '分配失败', content: res.error.message ?? '分配失败' });
      return;
    }
    setShowAssign(false);
    resetAssignForm();
    await refetch();
  };

  if (!online)
    return (
      <Result
        status="warning"
        title="当前处于离线状态"
        subTitle="请检查网络连接，恢复后重试"
        extra={<Button onClick={refetch}>重试</Button>}
      />
    );
  if (loading) return <Spin />;
  if (error)
    return (
      <Result
        status="error"
        title="加载失败"
        subTitle={error.message}
        extra={<Button onClick={refetch}>重试</Button>}
      />
    );

  const assignments = data?.content ?? [];

  return (
    <Space direction="vertical" size="large" style={{ width: '100%' }}>
      <Row justify="space-between" align="middle">
        <Typography.Title level={4} style={{ margin: 0 }}>
          任务分配
        </Typography.Title>
        <Space>
          <Button
            onClick={() => {
              resetSingleAssignForm();
              setShowSingleAssign(true);
            }}
          >
            分配任务
          </Button>
          <Button
            onClick={() => {
              resetAssignForm();
              setShowAssign(true);
            }}
          >
            批量分配
          </Button>
        </Space>
      </Row>

      <Card title="日历">
        <TaskCalendar
          baseMonth={calendarState.baseMonth}
          selectedRange={calendarState.selectedRange}
          onSelect={(action) => {
            type ActionMap = Record<string, CalendarAction2['type']>;
            const typeMap: ActionMap = {
              SELECT_DATE: 'SELECT_DATE',
              SELECT_WEEK: 'SELECT_WEEK',
              SELECT_MONTH: 'SELECT_MONTH',
            };
            dispatch({ type: typeMap[action.type], ...action } as CalendarAction2);
          }}
          onNavigate={(dir) => dispatch({ type: 'NAV_MONTH', payload: dir })}
        />
      </Card>

      <Card>
        <Space direction="vertical" size="small" style={{ width: '100%' }}>
          <TaskTypeFilter
            selected={calendarState.taskTypeFilters}
            onChange={(types) => dispatch({ type: 'SET_FILTERS', payload: types })}
          />
          <Button
            type={calendarState.viewAllMode ? 'primary' : 'default'}
            onClick={() => dispatch({ type: 'VIEW_ALL' })}
          >
            {calendarState.viewAllMode ? '查看全部（已激活）' : '查看全部'}
          </Button>
        </Space>
      </Card>

      <Card title="任务列表">
        <Space direction="vertical" size="small" style={{ width: '100%' }}>
          {assignments.map((a) => (
            <Card
              key={a.id}
              size="small"
              style={a.overdue ? { borderLeft: '4px solid #faad14' } : {}}
            >
              <Row justify="space-between" align="top">
                <Space direction="vertical" size={2}>
                  <Typography.Text strong>{a.snapshotTemplateName}</Typography.Text>
                  <Typography.Text type="secondary" style={{ fontSize: 12 }}>
                    {(() => {
                      const childName = childNameMap.get(a.childId) ?? `ID ${a.childId}`;
                      const label = repeatTaskLabel(
                        a.snapshotTemplateTaskType,
                        a.snapshotTemplateTypeConfig,
                      );
                      return label
                        ? `孩子：${childName} · ${label}`
                        : `孩子：${childName} · 截止 ${a.deadline}`;
                    })()}
                  </Typography.Text>
                  {a.overdue && (
                    <Typography.Text style={{ fontSize: 12, fontWeight: 600, color: '#faad14' }}>
                      已逾期
                    </Typography.Text>
                  )}
                </Space>
                <Space direction="vertical" size={2} align="end">
                  <Tag>{statusLabel(a.status.toLowerCase())}</Tag>
                  <Typography.Text type="secondary" style={{ fontSize: 12 }}>
                    {a.snapshotDifficultyReward} 积分
                  </Typography.Text>
                </Space>
              </Row>
            </Card>
          ))}
          {assignments.length === 0 && (
            <Typography.Text type="secondary">当天暂无任务</Typography.Text>
          )}
        </Space>
      </Card>

      <Modal
        open={showAssign}
        onCancel={() => setShowAssign(false)}
        title="批量分配任务"
        onOk={handleAssign}
        okText="分配"
        confirmLoading={assigning}
      >
        <Space direction="vertical" size="middle" style={{ width: '100%' }}>
          <div>
            <Typography.Text strong style={{ display: 'block', marginBottom: 4 }}>
              模板
            </Typography.Text>
            <Select
              id="assign-template"
              value={templateId.value || undefined}
              onChange={(v) => templateId.setValue(v)}
              placeholder="请选择模板"
              style={{ width: '100%' }}
            >
              {(templates?.content ?? []).map((t) => (
                <Select.Option key={t.id} value={String(t.id)}>
                  {t.name}
                </Select.Option>
              ))}
            </Select>
          </div>
          <div>
            <Typography.Text strong style={{ display: 'block', marginBottom: 4 }}>
              难度
            </Typography.Text>
            <Select
              id="assign-difficulty"
              value={difficultyId.value || undefined}
              onChange={(v) => difficultyId.setValue(v)}
              disabled={!selectedTemplate}
              placeholder="请选择难度"
              style={{ width: '100%' }}
            >
              {enabledDifficulties.map((d) => (
                <Select.Option key={d.id} value={String(d.id)}>
                  {d.name}（{d.rewardPoints} 积分）
                </Select.Option>
              ))}
            </Select>
          </div>
          <div>
            <Typography.Text strong style={{ display: 'block', marginBottom: 4 }}>
              孩子
            </Typography.Text>
            <Select
              id="assign-child"
              mode="multiple"
              value={childIds.map(String)}
              onChange={(values: string[]) => setChildIds(values.map(Number))}
              placeholder="请选择孩子"
              style={{ width: '100%' }}
            >
              {(children?.content ?? []).map((c) => (
                <Select.Option key={c.id} value={String(c.id)}>
                  {c.nickname}
                </Select.Option>
              ))}
            </Select>
            <Typography.Text type="secondary" style={{ fontSize: 12 }}>
              可选择多个孩子
            </Typography.Text>
          </div>
          <div>
            <Typography.Text strong style={{ display: 'block', marginBottom: 4 }}>
              开始日期
            </Typography.Text>
            <Input id="assign-start-date" type="date" {...startDate.inputProps} />
          </div>
          {selectedTemplate?.taskType !== 'REPEAT' && (
            <div>
              <Typography.Text strong style={{ display: 'block', marginBottom: 4 }}>
                结束日期
              </Typography.Text>
              <Input id="assign-end-date" type="date" {...endDate.inputProps} />
            </div>
          )}
        </Space>
      </Modal>

      {/* 单任务分配弹窗 */}
      <Modal
        open={showSingleAssign}
        onCancel={() => {
          setShowSingleAssign(false);
          resetSingleAssignForm();
        }}
        title="分配任务"
        onOk={handleSingleAssign}
        okText="分配"
        confirmLoading={singleAssigning}
      >
        <Space direction="vertical" size="middle" style={{ width: '100%' }}>
          <div>
            <Typography.Text strong style={{ display: 'block', marginBottom: 4 }}>
              模板
            </Typography.Text>
            <Select
              id="single-assign-template"
              value={singleTemplateId.value || undefined}
              onChange={(v) => {
                singleTemplateId.setValue(v);
                singleDifficultyId.reset();
              }}
              placeholder="请选择模板"
              style={{ width: '100%' }}
            >
              {(templates?.content ?? []).map((t) => (
                <Select.Option key={t.id} value={String(t.id)}>
                  {t.name}
                </Select.Option>
              ))}
            </Select>
          </div>
          <div>
            <Typography.Text strong style={{ display: 'block', marginBottom: 4 }}>
              难度
            </Typography.Text>
            <Select
              id="single-assign-difficulty"
              value={singleDifficultyId.value || undefined}
              onChange={(v) => singleDifficultyId.setValue(v)}
              disabled={!selectedSingleTemplate}
              placeholder="请选择难度"
              style={{ width: '100%' }}
            >
              {singleEnabledDifficulties.map((d) => (
                <Select.Option key={d.id} value={String(d.id)}>
                  {d.name}（{d.rewardPoints} 积分）
                </Select.Option>
              ))}
            </Select>
          </div>
          <div>
            <Typography.Text strong style={{ display: 'block', marginBottom: 4 }}>
              孩子
            </Typography.Text>
            <Select
              id="single-assign-child"
              value={singleChildId.value || undefined}
              onChange={(v) => singleChildId.setValue(v)}
              placeholder="请选择孩子"
              style={{ width: '100%' }}
            >
              {(children?.content ?? []).map((c) => (
                <Select.Option key={c.id} value={String(c.id)}>
                  {c.nickname}
                </Select.Option>
              ))}
            </Select>
          </div>
          {selectedSingleTemplate?.taskType !== 'REPEAT' && (
            <div>
              <Typography.Text strong style={{ display: 'block', marginBottom: 4 }}>
                截止日期
              </Typography.Text>
              <DatePicker
                id="single-assign-deadline"
                value={singleDeadline ? dayjs(singleDeadline) : null}
                onChange={(date) => setSingleDeadline(date ? date.format('YYYY-MM-DD') : '')}
                format="YYYY-MM-DD"
                style={{ width: '100%' }}
              />
            </div>
          )}
        </Space>
      </Modal>
    </Space>
  );
}

export function ParentReviewsPage() {
  const { data, loading, error, refetch } = useApi<PageResult<ReviewItem>>('/task-review/pending');
  const { data: history } = useApi<PageResult<ReviewItem>>('/task-review/history');
  const [reason, setReason] = useState('');
  const [active, setActive] = useState<ReviewItem | null>(null);
  const online = useOnline();
  const [submitting, setSubmitting] = useState(false);

  const decide = async (attemptId: number, approved: boolean) => {
    setSubmitting(true);
    await getClient().post(`/task-review/${attemptId}/${approved ? 'approve' : 'reject'}`, {
      reason: approved ? undefined : reason,
    });
    setSubmitting(false);
    setActive(null);
    setReason('');
    await refetch();
  };

  if (!online)
    return (
      <Result
        status="warning"
        title="当前处于离线状态"
        subTitle="请检查网络连接，恢复后重试"
        extra={<Button onClick={refetch}>重试</Button>}
      />
    );
  if (loading) return <Spin />;
  if (error)
    return (
      <Result
        status="error"
        title="加载失败"
        subTitle={error.message}
        extra={<Button onClick={refetch}>重试</Button>}
      />
    );

  const pending = data?.content ?? [];

  return (
    <Space direction="vertical" size="large" style={{ width: '100%' }}>
      <Typography.Title level={4} style={{ margin: 0 }}>
        任务审核
      </Typography.Title>

      <Card title="待审核">
        <Space direction="vertical" size="small" style={{ width: '100%' }}>
          {pending.length === 0 ? (
            <Typography.Text type="secondary">暂无待审核任务</Typography.Text>
          ) : (
            pending.map((item) => (
              <Card
                key={item.attemptId}
                size="small"
                style={item.isOverdue ? { borderLeft: '4px solid #faad14' } : {}}
              >
                <Row justify="space-between" align="top">
                  <Space direction="vertical" size={2}>
                    <Typography.Text strong>{item.templateTitle}</Typography.Text>
                    <Typography.Text type="secondary" style={{ fontSize: 12 }}>
                      {item.childNickname} · {item.submittedAt}
                    </Typography.Text>
                    {item.notes && (
                      <Typography.Text style={{ fontSize: 12 }}>{item.notes}</Typography.Text>
                    )}
                    {item.isOverdue && (
                      <Typography.Text style={{ fontSize: 12, fontWeight: 600, color: '#faad14' }}>
                        已逾期
                      </Typography.Text>
                    )}
                  </Space>
                  <Space direction="vertical" size={2}>
                    <Button
                      size="small"
                      onClick={() => decide(item.attemptId, true)}
                      loading={submitting}
                    >
                      通过
                    </Button>
                    <Button
                      danger
                      size="small"
                      onClick={() => setActive(item)}
                      loading={submitting}
                    >
                      驳回
                    </Button>
                  </Space>
                </Row>
              </Card>
            ))
          )}
        </Space>
      </Card>

      <Card title="审核历史">
        <Space direction="vertical" size="small" style={{ width: '100%' }}>
          {(history?.content ?? []).length === 0 ? (
            <Typography.Text type="secondary">暂无历史</Typography.Text>
          ) : (
            (history?.content ?? []).map((item) => (
              <Card key={item.attemptId} size="small">
                <Typography.Text strong>{item.templateTitle}</Typography.Text>
                <Typography.Text type="secondary" style={{ display: 'block', fontSize: 12 }}>
                  {item.childNickname} · {item.submittedAt}
                </Typography.Text>
              </Card>
            ))
          )}
        </Space>
      </Card>

      <Modal
        open={!!active}
        onCancel={() => {
          setActive(null);
          setReason('');
        }}
        title="驳回原因"
        footer={[
          <Button
            key="cancel"
            onClick={() => {
              setActive(null);
              setReason('');
            }}
          >
            取消
          </Button>,
          <Button
            key="reject"
            danger
            onClick={() => active && decide(active.attemptId, false)}
            loading={submitting}
            disabled={!reason.trim()}
          >
            确认驳回
          </Button>,
        ]}
      >
        <TextArea
          value={reason}
          onChange={(e) => setReason(e.target.value)}
          placeholder="请输入驳回原因"
          aria-label="驳回原因"
        />
      </Modal>
    </Space>
  );
}

export function ParentPointsPage() {
  const { data: children } = useApi<PageResult<ChildProfile>>('/family/children');
  const [selectedChild, setSelectedChild] = useState('');
  const { data, loading, error, refetch } = useApi<{
    currentBalance: number;
    content: {
      id: number;
      amount: number;
      type: string;
      createdAt: string;
      reason?: string;
    }[];
  }>(selectedChild ? `/points/ledger/${selectedChild}` : '', { skip: !selectedChild });
  const online = useOnline();
  const amount = useFormField();
  const reason = useFormField();
  const [adjusting, setAdjusting] = useState(false);

  const handleAdjust = async () => {
    if (!selectedChild) return;
    const amt = Number(amount.value);
    if (!amt || !reason.value.trim()) {
      message.error('请填写调整数量和原因');
      return;
    }
    const ref = `${Date.now()}_${Math.random().toString(36).substring(2, 8)}`;
    setAdjusting(true);
    const res = await getClient().post('/points/adjustments', {
      childId: Number(selectedChild),
      amount: amt,
      reason: reason.value,
      businessRef: ref,
    });
    setAdjusting(false);
    if (res.error) {
      message.error(res.error.message ?? '积分调整失败');
      return;
    }
    amount.reset();
    reason.reset();
    message.success('积分已调整');
    await refetch();
  };

  if (!online)
    return (
      <Result
        status="warning"
        title="当前处于离线状态"
        subTitle="请检查网络连接，恢复后重试"
        extra={<Button onClick={refetch}>重试</Button>}
      />
    );
  if (loading) return <Spin />;
  if (error)
    return (
      <Result
        status="error"
        title="加载失败"
        subTitle={error.message}
        extra={<Button onClick={refetch}>重试</Button>}
      />
    );

  return (
    <Space direction="vertical" size="large" style={{ width: '100%' }}>
      <Typography.Title level={4} style={{ margin: 0 }}>
        积分
      </Typography.Title>

      <Card title="选择孩子">
        <Select
          value={selectedChild || undefined}
          onChange={(v) => setSelectedChild(v)}
          placeholder="请选择孩子"
          style={{ width: '100%' }}
        >
          {(children?.content ?? []).map((c) => (
            <Select.Option key={c.id} value={String(c.id)}>
              {c.nickname}
            </Select.Option>
          ))}
        </Select>
      </Card>

      {selectedChild && (
        <>
          <Card title="积分余额">
            <Typography.Title level={2} style={{ margin: 0 }}>
              {data?.currentBalance ?? 0} 积分
            </Typography.Title>
          </Card>
          <Card title="积分调整">
            <Space direction="vertical" size="middle" style={{ width: '100%' }}>
              <div>
                <Typography.Text strong style={{ display: 'block', marginBottom: 4 }}>
                  调整数量（正数奖励、负数扣除）
                </Typography.Text>
                <Input id="adjust-amount" type="number" {...amount.inputProps} />
              </div>
              <div>
                <Typography.Text strong style={{ display: 'block', marginBottom: 4 }}>
                  原因
                </Typography.Text>
                <Input id="adjust-reason" {...reason.inputProps} />
              </div>
              <Button onClick={handleAdjust} loading={adjusting}>
                确认调整
              </Button>
            </Space>
          </Card>
          <Card title="流水">
            <Space direction="vertical" size="small" style={{ width: '100%' }}>
              {(data?.content ?? []).map((tx) => (
                <Row key={tx.id} justify="space-between" align="middle">
                  <Space direction="vertical" size={0}>
                    <Typography.Text>{tx.reason ?? tx.type}</Typography.Text>
                    <Typography.Text type="secondary" style={{ fontSize: 12 }}>
                      {tx.createdAt}
                    </Typography.Text>
                  </Space>
                  <Typography.Text strong style={{ color: tx.amount >= 0 ? '#52c41a' : '#ff4d4f' }}>
                    {tx.amount > 0 ? '+' : ''}
                    {tx.amount}
                  </Typography.Text>
                </Row>
              ))}
              {(data?.content ?? []).length === 0 && (
                <Typography.Text type="secondary">暂无流水</Typography.Text>
              )}
            </Space>
          </Card>
        </>
      )}
    </Space>
  );
}

export function ParentPrizesPage() {
  const { items, loading, error, refetch, page, pageSize, setPage, total } =
    usePaginatedData<Prize>('/prizes');
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState<Prize | null>(null);
  const name = useFormField();
  const description = useFormField();
  const pointsCost = useFormField('0');
  const availableStock = useFormField('0');
  const online = useOnline();
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);

  const prizeTypeValue = useFormField('PHYSICAL');
  const prizeCategoryValue = useFormField();
  const titleImage = useFormField();
  const detailImage = useFormField();
  const validFrom = useFormField();
  const validTo = useFormField();
  const typeConfigValue = useFormField();

  const prizeTypeConfig = useMemo(
    (): PrizeTypeConfig => ({
      prizeType: (prizeTypeValue.value as 'VIRTUAL' | 'PHYSICAL') || 'PHYSICAL',
      prizeCategory: (prizeCategoryValue.value as any) || undefined,
      titleImage: titleImage.value || undefined,
      detailImage: detailImage.value || undefined,
      validFrom: validFrom.value || undefined,
      validTo: validTo.value || undefined,
      typeConfig: typeConfigValue.value || undefined,
    }),
    [
      prizeTypeValue.value,
      prizeCategoryValue.value,
      titleImage.value,
      detailImage.value,
      validFrom.value,
      validTo.value,
      typeConfigValue.value,
    ],
  );

  const handleUpload = async (file: File): Promise<string> => {
    const formData = new FormData();
    formData.append('file', file);
    const res = await getClient().post<{ url: string }>('/prizes/upload', formData);
    if (res.error) throw new Error(res.error.message);
    if (!res.data?.url) throw new Error('上传返回的 URL 为空');
    return res.data.url;
  };

  const openNew = () => {
    setEditing(null);
    name.reset();
    description.reset();
    pointsCost.setValue('0');
    availableStock.setValue('0');
    prizeTypeValue.setValue('PHYSICAL');
    prizeCategoryValue.reset();
    titleImage.reset();
    detailImage.reset();
    validFrom.reset();
    validTo.reset();
    typeConfigValue.reset();
    setSaveError(null);
    setShowModal(true);
  };

  const openEdit = (p: Prize) => {
    setEditing(p);
    name.setValue(p.name);
    description.setValue(p.description);
    pointsCost.setValue(String(p.pointsCost));
    availableStock.setValue(String(p.availableStock));
    prizeTypeValue.setValue(p.prizeType ?? 'PHYSICAL');
    prizeCategoryValue.setValue(p.prizeCategory ?? '');
    titleImage.setValue(p.titleImage ?? '');
    detailImage.setValue(p.detailImage ?? '');
    validFrom.setValue(p.validFrom ?? '');
    validTo.setValue(p.validTo ?? '');
    typeConfigValue.setValue(p.typeConfig ?? '');
    setSaveError(null);
    setShowModal(true);
  };

  const handleSave = async () => {
    setSaving(true);
    setSaveError(null);
    const payload = {
      name: name.value,
      description: description.value,
      pointsCost: Number(pointsCost.value),
      availableStock: Number(availableStock.value),
      prizeType: prizeTypeValue.value,
      prizeCategory: prizeCategoryValue.value || undefined,
      titleImage: titleImage.value || undefined,
      detailImage: detailImage.value || undefined,
      validFrom: validFrom.value || undefined,
      validTo: validTo.value || undefined,
      typeConfig: typeConfigValue.value || undefined,
    };
    const res = editing
      ? await getClient().put(`/prizes/${editing.id}`, payload)
      : await getClient().post('/prizes', payload);
    setSaving(false);
    if (res.error) {
      setSaveError(res.error.message ?? '保存失败');
      return;
    }
    setShowModal(false);
    message.success('保存成功');
    await refetch();
  };

  const handleDeletePrize = async (id: number) => {
    await getClient().delete(`/prizes/${id}`);
    await refetch();
  };

  const togglePrizeEnabled = async (p: Prize) => {
    const payload = {
      name: p.name,
      description: p.description,
      pointsCost: p.pointsCost,
      availableStock: p.availableStock,
      enabled: !p.enabled,
    };
    await getClient().put(`/prizes/${p.id}`, payload);
    await refetch();
  };

  if (!online)
    return (
      <Result
        status="warning"
        title="当前处于离线状态"
        subTitle="请检查网络连接，恢复后重试"
        extra={<Button onClick={refetch}>重试</Button>}
      />
    );
  if (loading) return <Spin />;
  if (error)
    return (
      <Result
        status="error"
        title="加载失败"
        subTitle={error.message}
        extra={<Button onClick={refetch}>重试</Button>}
      />
    );

  return (
    <Space direction="vertical" size="large" style={{ width: '100%' }}>
      <Row justify="space-between" align="middle">
        <Typography.Title level={4} style={{ margin: 0 }}>
          奖品
        </Typography.Title>
        <Button onClick={openNew}>新增奖品</Button>
      </Row>

      <Table
        dataSource={items}
        rowKey="id"
        loading={loading}
        pagination={{
          current: page + 1,
          total,
          pageSize,
          onChange: (p) => setPage(p - 1),
        }}
        columns={[
          { title: '奖品名称', dataIndex: 'name', key: 'name' },
          { title: '积分', dataIndex: 'pointsCost', key: 'pointsCost' },
          { title: '库存', dataIndex: 'availableStock', key: 'availableStock' },
          {
            title: '类型',
            key: 'prizeType',
            render: (_: unknown, record: Prize) => {
              if (record.prizeType === 'VIRTUAL') {
                const labels: Record<string, string> = {
                  TV_TIME: '电视时长卡',
                  COMPUTER_TIME: '电脑时长卡',
                  PARK_PLAY: '公园游玩卡',
                  GENERAL: '通用',
                  TRAVEL: '旅游卡',
                };
                return (
                  <Tag color="blue">
                    虚拟 · {labels[record.prizeCategory ?? ''] || record.prizeCategory}
                  </Tag>
                );
              }
              return <Tag>实物</Tag>;
            },
          },
          {
            title: '状态',
            key: 'enabled',
            render: (_: unknown, record: Prize) => (
              <Tag color={record.enabled ? 'success' : 'default'}>
                {record.enabled ? '启用' : '停用'}
              </Tag>
            ),
          },
          {
            title: '操作',
            key: 'actions',
            render: (_: unknown, record: Prize) => (
              <Space>
                <Button type="text" size="small" onClick={() => openEdit(record)}>
                  编辑
                </Button>
                <Button size="small" onClick={() => togglePrizeEnabled(record)}>
                  {record.enabled ? '停用' : '启用'}
                </Button>
                <Button
                  danger
                  size="small"
                  onClick={() => {
                    Modal.confirm({
                      title: '确认删除',
                      content: '删除奖品将影响相关兑换记录，确认删除？',
                      okText: '确认删除',
                      okType: 'danger',
                      cancelText: '取消',
                      onOk: () => handleDeletePrize(record.id),
                    });
                  }}
                >
                  删除
                </Button>
              </Space>
            ),
          },
        ]}
      />

      <Modal
        open={showModal}
        onCancel={() => setShowModal(false)}
        title={editing ? '编辑奖品' : '新增奖品'}
        okText="保存"
        onOk={handleSave}
        confirmLoading={saving}
        width={640}
      >
        <Space direction="vertical" size="middle" style={{ width: '100%' }}>
          {saveError && <Alert message={saveError} type="error" showIcon />}
          <div>
            <Typography.Text strong style={{ display: 'block', marginBottom: 4 }}>
              名称
            </Typography.Text>
            <Input id="prize-name" {...name.inputProps} />
          </div>
          <div>
            <Typography.Text strong style={{ display: 'block', marginBottom: 4 }}>
              描述
            </Typography.Text>
            <TextArea id="prize-desc" {...description.inputProps} />
          </div>
          <div>
            <Typography.Text strong style={{ display: 'block', marginBottom: 4 }}>
              积分价格
            </Typography.Text>
            <Input id="prize-cost" type="number" {...pointsCost.inputProps} />
          </div>
          <div>
            <Typography.Text strong style={{ display: 'block', marginBottom: 4 }}>
              库存
            </Typography.Text>
            <Input id="prize-stock" type="number" {...availableStock.inputProps} />
          </div>
          <PrizeTypeConfigForms
            value={prizeTypeConfig}
            onChange={(v) => {
              prizeTypeValue.setValue(v.prizeType);
              prizeCategoryValue.setValue(v.prizeCategory ?? '');
              titleImage.setValue(v.titleImage ?? '');
              detailImage.setValue(v.detailImage ?? '');
              validFrom.setValue(v.validFrom ?? '');
              validTo.setValue(v.validTo ?? '');
              typeConfigValue.setValue(v.typeConfig ?? '');
            }}
            onUpload={handleUpload}
          />
        </Space>
      </Modal>
    </Space>
  );
}

